// ║ WhatsApp Business (vía Twilio)                                          ║
// ║ Env vars requeridas en Cloud Run:                                        ║
// ║   TWILIO_ACCOUNT_SID   (ACxxxx…)                                        ║
// ║   TWILIO_AUTH_TOKEN    (secret)                                          ║
// ║   TWILIO_WA_FROM       (formato "whatsapp:+14155238886" sandbox         ║
// ║                          o "whatsapp:+17542903346" producción)          ║
// ║ Modelo: mensaje libre (dentro de ventana 24h del huésped) o template   ║
// ║ pre-aprobado por Meta (fuera de ventana). Twilio expone template       ║
// ║ mediante ContentSid del Content Template Builder.                       ║
// ═══════════════════════════════════════════════════════════════════════════

/** Normaliza destino a formato "whatsapp:+52…". Acepta "8115569120",
 *  "5218115569120", "+528115569120", "+52 811 556 9120", etc. */
function _waFormatToSingle(to) {
  let s = String(to || "").trim().replace(/[^\d+]/g, "");
  if (!s) return "";
  if (s.startsWith("whatsapp:")) return s;
  if (!s.startsWith("+")) {
    if (s.length === 10) s = "+521" + s;
    else if (s.length === 12 && s.startsWith("52")) s = "+521" + s.slice(2);
    else if (s.length === 13 && s.startsWith("521")) s = "+" + s;
    else s = "+" + s;
  } else {
    if (/^\+52\d{10}$/.test(s)) s = "+521" + s.slice(3);
  }
  return "whatsapp:" + s;
}
/** Devuelve un array de recipients normalizados (acepta CSV o array). */
function _waFormatToList(to) {
  if (!to) return [];
  const arr = Array.isArray(to) ? to : String(to).split(/[,;]+/);
  return arr.map(_waFormatToSingle).filter(Boolean);
}
/** Compat: devuelve solo el primero (para endpoints que aún esperan string). */
function _waFormatTo(to) {
  const arr = _waFormatToList(to);
  return arr[0] || "";
}

// Twilio WA impone límite ~1600 chars por mensaje. Cuando el body excede,
// dividimos por saltos de línea en chunks ≤ MAX y enviamos en secuencia.
// Mantiene ordenamiento: espera cada envío antes del siguiente.
const TWILIO_WA_MAX_CHARS = 1500;
function _splitForTwilio(text, max) {
  const s = String(text || '');
  if (s.length <= max) return [s];
  const chunks = [];
  const lines = s.split('\n');
  let cur = '';
  for (const line of lines) {
    // Si el propio line excede max, córtalo duro por chars.
    if (line.length > max) {
      if (cur) { chunks.push(cur); cur = ''; }
      for (let i = 0; i < line.length; i += max) chunks.push(line.slice(i, i + max));
      continue;
    }
    const cand = cur ? cur + '\n' + line : line;
    if (cand.length > max) { chunks.push(cur); cur = line; }
    else cur = cand;
  }
  if (cur) chunks.push(cur);
  return chunks;
}
// logChat: true → el mensaje enviado queda en el hilo del panel (Chats bot). Para avisos al personal que antes
// se mandaban con skipMirror y no se guardaban (asistencia, cierre de jornada, emergencias, avisos al admin).
function _twilioLogChat(params, body, j) {
  try { const p10 = String(params.to || "").replace(/\D/g, "").slice(-10); if (p10.length === 10 && body) _botAppendMessage(p10, "assistant", String(body), Object.assign({ sid: j && j.sid, staff: true }, params.logMeta || {})).catch(() => {}); } catch (_) {}
}
// ═══ Varios números de WhatsApp (2026-10-19) ═══════════════════════════════════════════════════════════════
// TWILIO_WA_FROM = número principal (pruebas, EE.UU.): todos los módulos. whatsapp/numeros.json = números adicionales
// (p. ej. el del negocio en México) con interruptor general y por módulo: bot (respuestas a huéspedes), personal
// (asistencia y bot del personal/admin), programados (mensajes automáticos a huéspedes), avisos (al personal/admin/emergencias).
// Se contesta desde el número que recibió el mensaje; las respuestas del panel salen por el último número que usó ese contacto.
const { AsyncLocalStorage } = require("async_hooks");
const _WA_ALS = new AsyncLocalStorage();
const _WA_NUM_OBJ = "whatsapp/numeros.json", _WA_NUMTEL_OBJ = "whatsapp/numero-por-tel.json";
const _WA_MODULOS = ["bot", "personal", "programados", "avisos"];
let _waNumC = { d: null, ts: 0 }, _waNumTel = null, _waPersC = { s: null, ts: 0 };
const _waNorm = v => { const d = String(v || "").replace(/\D/g, ""); return d ? "whatsapp:+" + d : ""; };
const _waPrincipal = () => String(process.env.TWILIO_WA_FROM || "");
async function _waNumeros(fresh) {
  if (!fresh && _waNumC.d && Date.now() - _waNumC.ts < 15e3) return _waNumC.d;
  const d = await _rhdGetJson(_WA_NUM_OBJ).catch(() => ({}));
  const L = Array.isArray(d.numeros) ? d.numeros : [{ from: "whatsapp:+528444443922", nombre: "Negocio México", activo: false, modulos: {} }];
  _waNumC = { d: L, ts: Date.now() }; return L;
}
async function _waNumCtx(to) {
  const t = _waNorm(to); if (!t || t === _waNorm(_waPrincipal())) return { from: _waPrincipal(), principal: true };
  const n = (await _waNumeros().catch(() => [])).find(x => _waNorm(x.from) === t);
  return { from: t, principal: false, activo: !!(n && n.activo), modulos: (n && n.modulos) || {}, nombre: (n && n.nombre) || t };
}
async function _waNumTelMapa() { if (!_waNumTel) _waNumTel = (await _rhdGetJson(_WA_NUMTEL_OBJ).catch(() => ({}))) || {}; return _waNumTel; }
async function _waNumTelSet(p10, from) { const M = await _waNumTelMapa(); if ((M[p10] || "") === (from || "")) return; if (from) M[p10] = from; else delete M[p10]; _rhdPut(_WA_NUMTEL_OBJ, JSON.stringify(M), "application/json").catch(() => {}); }
async function _waEsPersonal(p10) {
  if (!_waPersC.s || Date.now() - _waPersC.ts > 10 * 60e3) { const S = new Set(), add = v => { const x = _sisCel10(v); if (x) S.add(x); };
    (await _sisLeer("per").catch(() => ({ rows: [] }))).rows.forEach(r => { add(r.Celular); add(r.Telefono); });
    (await _sisLeer("su").catch(() => ({ rows: [] }))).rows.forEach(r => add(_sisCol(r, "cel", "celular", "whatsapp")));
    _waPersC = { s: S, ts: Date.now() }; }
  return _waPersC.s.has(String(p10));
}
// Remitente: con módulo → el número activo que tenga ese módulo (o el principal); sin módulo → el número del mensaje que se está
// contestando, o el último que usó ese contacto, o el principal.
async function _waFromPara(to, modulo) {
  const L = (await _waNumeros().catch(() => [])).filter(n => n.activo);
  if (modulo) { const n = L.find(x => (x.modulos || {})[modulo]); return n ? _waNorm(n.from) : _waPrincipal(); }
  const st = _WA_ALS.getStore(); if (st && st.from) return st.from;
  const p10 = String(to || "").replace(/\D/g, "").slice(-10), f = (await _waNumTelMapa().catch(() => ({})))[p10];
  return f && L.some(n => _waNorm(n.from) === f) ? f : _waPrincipal();
}
app.get("/wa/numeros", async (req, res) => {
  res.set("Cache-Control", "no-store");
  try { res.json({ ok: true, principal: _waPrincipal(), modulos: _WA_MODULOS, numeros: await _waNumeros(true) }); } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.post("/wa/numeros", async (req, res) => {
  if (!_vOriginOk(req)) return res.status(403).json({ ok: false, error: "Origen no permitido" });
  try {
    const L = (Array.isArray((req.body || {}).numeros) ? req.body.numeros : []).map(n => ({ from: _waNorm(n.from), nombre: String(n.nombre || "").slice(0, 60), activo: !!n.activo,
      modulos: Object.fromEntries(_WA_MODULOS.map(k => [k, !!(n.modulos || {})[k]])) })).filter(n => n.from && n.from !== _waNorm(_waPrincipal()));
    await _rhdPut(_WA_NUM_OBJ, JSON.stringify({ numeros: L, at: new Date().toISOString(), por: String((req.body || {}).usuario || "").slice(0, 60) }), "application/json");
    _waNumC = { d: L, ts: Date.now() }; res.json({ ok: true, numeros: L });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
async function _twilioSendMessage(params) {
  // Si el body supera el límite Twilio, dividir y enviar en secuencia.
  // Cada chunk como mensaje WA independiente; en WA_ChatContext registramos
  // 1 sola entrada con el body ORIGINAL completo (fire-and-forget) para no
  // saturar el historial con N filas.
  if (params.body && String(params.body).length > TWILIO_WA_MAX_CHARS && !params.contentSid) {
    const originalBody = String(params.body);
    const chunks = _splitForTwilio(originalBody, TWILIO_WA_MAX_CHARS);
    let last = null;
    for (let i = 0; i < chunks.length; i++) {
      const p = { ...params, body: chunks[i], skipMirror: true, logChat: false };
      last = await _twilioSendMessage(p);
    }
    if (params.logChat && last) _twilioLogChat(params, originalBody, last);
    // Mirror único con el body completo, si el caller no pidió skipMirror.
    if (!params.skipMirror && last) {
      try {
        const phone10 = String(params.to || '').replace(/\D/g,'').slice(-10);
        if (phone10.length === 10) {
          fetch(CHECKIN_APPS_SCRIPT_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify({
              action: 'wa_chat_context_append',
              phone: phone10,
              role: params.tipo ? 'template' : 'admin',
              body: originalBody,
              meta: { sid: last.sid, tipo: params.tipo || '', chunks: chunks.length }
            })
          }).catch(()=>{});
        }
      } catch(_){}
    }
    return last;
  }
  const sid    = process.env.TWILIO_ACCOUNT_SID;
  const keySid = process.env.TWILIO_API_KEY_SID;
  const keySec = process.env.TWILIO_API_KEY_SECRET;
  const token  = process.env.TWILIO_AUTH_TOKEN; // fallback si aún no hay API Key
  const from   = params.from || await _waFromPara(params.to, params.modulo).catch(() => process.env.TWILIO_WA_FROM);
  const user = keySid || sid;
  const pass = keySec || token;
  if (!sid || !user || !pass || !from) {
    throw new Error("Twilio env vars faltantes (necesito TWILIO_ACCOUNT_SID + TWILIO_API_KEY_SID/SECRET o TWILIO_AUTH_TOKEN + TWILIO_WA_FROM)");
  }
  const body = new URLSearchParams();
  body.set("From", from);
  body.set("To",   params.to);
  if (params.body)          body.set("Body", params.body);
  if (params.contentSid)    body.set("ContentSid", params.contentSid);
  if (params.contentVars)   body.set("ContentVariables", JSON.stringify(params.contentVars));
  const auth = Buffer.from(user + ":" + pass).toString("base64");
  const r = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`, {
    method: "POST",
    headers: { "Authorization": "Basic " + auth, "Content-Type": "application/x-www-form-urlencoded" },
    body: body.toString(),
  });
  const j = await r.json();
  if (!r.ok) throw new Error(`Twilio ${r.status}: ${j.message || JSON.stringify(j).slice(0,200)}`);
  if (params.logChat) _twilioLogChat(params, params.body, j);
  // MIRROR a WA_ChatContext (fire-and-forget) — así los envíos outbound
  // (templates, cron, /wa/send manual) también aparecen en el hilo del
  // panel bot-chats. Skip si el destino no tiene formato válido o si el
  // caller pasó skipMirror:true (bot/admin ya loguean por su cuenta y
  // duplicarían el mensaje).
  try {
    const phone10 = String(params.to || "").replace(/\D/g,"").slice(-10);
    if (!params.skipMirror && phone10.length === 10) {
      const bodyForLog = String(params.body || (params.contentSid ? `(template ${params.contentSid})` : ""));
      if (bodyForLog) {
        fetch(CHECKIN_APPS_SCRIPT_URL, {
          method: "POST",
          headers: { "Content-Type": "text/plain;charset=utf-8" },
          body: JSON.stringify({
            action: "wa_chat_context_append",
            phone: phone10,
            role: params.tipo ? "template" : "admin",
            body: bodyForLog,
            meta: { sid: j.sid, tipo: params.tipo || "", contentSid: params.contentSid || "" }
          })
        }).catch(()=>{});
      }
    }
  } catch(_) {}
  return j;
}

// POST /wa/send — envía WhatsApp (freeform si "body", o template si "contentSid").
// Body: { to, body?, contentSid?, contentVars?, bookingId? (para log), tipo? }
// ═══════════════════════════════════════════════════════════════════════════
// ║ BOT IA WHATSAPP — Webhook inbound + Claude Haiku + tools               ║
// ║                                                                          ║
// ║ Flujo: Twilio webhook → /wa/webhook-inbound → identifica reserva →     ║
// ║   arma contexto alojamiento → llama Claude → responde vía Twilio →      ║
// ║   loguea en WA_ChatContext (Apps Script).                                ║
// ║                                                                          ║
// ║ Piloto restringido: solo responde a huéspedes cuya reserva tiene un     ║
// ║ HouseId con bot_enabled=TRUE en la hoja alojamientos.                    ║
// ═══════════════════════════════════════════════════════════════════════════
const BOT_ANTHROPIC_MODEL = "claude-sonnet-5";

// ═══════════════════════════════════════════════════════════════════════════
// ║ Bot Prompts (procesos del negocio) — cache in-memory TTL 5 min.        ║
// ║ Se lee UNA vez desde Apps Script y se inyecta en cada system prompt.   ║
// ║ Invalidación manual: POST /wa/bot/prompts/reload (lo hace la UI al     ║
// ║ guardar).                                                                ║
// ═══════════════════════════════════════════════════════════════════════════
let _botPromptsCache = { ts: 0, rows: [] };
const _BOT_PROMPTS_TTL = 5 * 60 * 1000;
// Las instrucciones por proceso viven en Control del bot › Procesos (ficha de cada proceso).
// opts.admin → incluye los procesos de administración · opts.claves → procesos detectados en el mensaje.
async function _botGetPrompts(opts) {
  opts = opts || {};
  try {
    const cfg = await _bcCfg(), catL = _bcCatalogo(cfg), quiero = new Set(_BC_CORE.concat(opts.claves || []));
    // Flujos marcados «El bot responde con estas plantillas»: sus plantillas entran al prompt como formato de respuesta del proceso.
    const FR = (cfg.flujos || []).filter(f => f.respuesta && (f.pasos || []).length), TP = FR.length ? ((await _waLeer(_WA_OBJ.tpl).catch(() => ({}))).items || []) : [];
    const plantDe = k => FR.filter(f => f.proceso === k).flatMap(f => f.pasos.map((id, i) => { const t = TP.find(x => x.id === id); return t && t.body ? { paso: f.ordenado !== false ? i + 1 : 0, nombre: t.nombre, body: String(t.body).replace(/\u000b/g, "\n") } : null; })).filter(Boolean);
    return catL.filter(c => {
      const pc = cfg.procesos[c.clave] || {}, f = pc.ficha || {};
      if (!Object.values(f).some(v => String(v || "").trim())) return false;
      if (c.admin) return !!opts.admin;
      if (cfg.activo && (pc.modo || c.modoIni) === "off") return false;
      return opts.todos || quiero.has(c.clave);
    }).map(c => { const f = (cfg.procesos[c.clave] || {}).ficha || {};
      return { Plantillas: plantDe(c.clave), Nombre: c.nombre, Activo: true, Objetivo: f.objetivo || c.desc, Datos_obtener: f.obtener || "", Datos_compartir: f.compartir || "", Reglas: f.reglas || "", Flujo: f.flujo || "", Riesgos: f.riesgos || "", Herramienta: (c.tools || []).join(", ") || f.herramienta || "" }; });
  } catch (e) { console.warn("[bot-prompts] fichas:", e.message); return []; }
}
function _botBuildPromptsBlock(prompts) {
  if (!prompts || !prompts.length) return "";
  const bullets = arr => (arr || "").split(/\||\n/).map(s => s.trim()).filter(Boolean).map(s => "     · " + s).join("\n");
  const secs = prompts.map(p => {
    const parts = [`### ${p.Nombre}`];
    if (p.Objetivo)        parts.push(`   Objetivo: ${p.Objetivo}`);
    if (p.Trigger)         parts.push(`   Detección (cuándo aplica):\n${bullets(p.Trigger)}`);
    if (p.Datos_obtener)   parts.push(`   Datos a obtener del huésped:\n${bullets(p.Datos_obtener)}`);
    if (p.Datos_compartir) parts.push(`   Datos que puedes compartir:\n${bullets(p.Datos_compartir)}`);
    if (p.Reglas)          parts.push(`   Reglas del negocio (LÍNEAS DURAS — no negociables):\n${bullets(p.Reglas)}`);
    if (p.Flujo)           parts.push(`   Flujo esperado:\n${bullets(p.Flujo)}`);
    if (p.Riesgos)         parts.push(`   Riesgos / prohibiciones:\n${bullets(p.Riesgos)}`);
    if (p.Herramienta)     parts.push(`   Herramienta vinculada: ${p.Herramienta}`);
    if (p.Plantillas && p.Plantillas.length) parts.push(`   PLANTILLAS DE RESPUESTA (usa esta redacción y formato; cambia solo los datos entre {{ }} por los reales y el saludo/nombre según la conversación; envía la que corresponda al paso en que va la conversación, no todas):\n${p.Plantillas.map(t => `     ${t.paso ? `Paso ${t.paso} · ` : ""}«${t.nombre}»:\n${String(t.body).split("\n").map(l => "        " + l).join("\n")}`).join("\n")}`);
    return parts.join("\n");
  }).join("\n\n");
  return `

═══════════════════════════════════════════════════════════════════════
PROCESOS DEL NEGOCIO — reglas por proceso (los administradores las editan
en el panel; síguelas SIEMPRE por encima de cualquier otra guía):
═══════════════════════════════════════════════════════════════════════

${secs}

═══════════════════════════════════════════════════════════════════════`;
}
