  (_aseo.rows || []).forEach(x => { if (String(x.HouseId) === String(hid)) m.set(String(x.Id), { Status: x.Status, dep: x.DateDeparture, arr: x.DateArrival, guest: x.GuestName || (m.get(String(x.Id)) || {}).guest || "" }); });
