  const est = pub ? pub.estado : "pendiente";
  let modo = "";
  if (salHoy) modo = est !== "pendiente" ? "aseo" : (entHoy && horaMx >= 14 ? "" : "desocupa");
  else if (entHoy) modo = (est === "terminado" || est === "inspeccionado") ? "aseo" : "";
