        evidencia: L.slice(0, 12).map(x => ({ bid: x.s.bid, fecha: x.s.fecha, aloj: x.s.aloj, fuente: x.s.fuente, huesped: x.s.huesped, anfitrion: x.s.anfitrion, resolucion: x.resolucion || "" })),
